"Agent when the app opens": "アプリを開いたときのエージェント",
"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "エージェントは4種類のステップで操作します：コマンドの実行、ファイルの読み取り、ファイルの書き込み、ファイルの一部の編集。コマンドを実行する前やファイルを変更する前には、その内容が正確に表示され、「実行」（または「適用」）、「スキップ」、「このチャットでは常に許可」から選べます。現在のフォルダ内のファイルの読み取りには承認は不要です。",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "エージェントは間違えることがあります。実行しようとしている内容をよく読んでください。特に動作モードやRootでは、コマンドによってアプリが削除されたり設定が変更されたりすることがあります。",
"Agents only see what you send and what their steps return; keys and tokens in output are hidden from them.": "エージェントが見られるのは、あなたが送った内容と、ステップが返した結果だけです。出力に含まれるキーやトークンはエージェントには伏せられます。",
"Agents to add it to": "追加先のエージェント",
"Airplane mode": "機内モード",
"Airplane mode off": "機内モードをオフにする",
"Airplane mode on": "機内モードをオンにする",
"Alarm": "アラーム",
"Alcatel": "Alcatel",
"Alert me when these apps come back, for example after a system update": "これらのアプリが再び有効になったとき（システムアップデート後など）に通知します",
"All": "すべて",
"All ADB connections are dropped. Your phone will ask \"Allow debugging?\" again, and Wireless Debugging must be paired again.": "すべてのADB接続が切断されます。端末で「デバッグを許可しますか？」が再度表示され、ワイヤレスデバッグは再度ペア設定が必要になります。",
"All Apps (": "すべてのアプリ(",
