"All installed apps are shown. To enable Freeze, Uninstall, or ADB commands, connect via ADB TCP 5555, Wireless Debugging, Shizuku, or Root.": "インストール済みのすべてのアプリを表示しています。凍結、アンインストール、ADBコマンドを使うには、ADB TCP 5555、ワイヤレスデバッグ、Shizuku、Rootのいずれかで接続してください。",
