"App: ADB Application Manager Pro ? (build ?)": "アプリ：ADB Application Manager Pro ?（ビルド ?）",
"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner は、ファイルアクセスでは届かないキャッシュ（アプリの「ストレージ」画面の「キャッシュを消去」ボタン）を、システム設定を代わりにタップして消去できます。そのためにこのアプリのユーザー補助サービスが必要です。サービスは AppCleaner がキャッシュを消去している間だけ動作します。アプリごとに「アプリ情報」画面を開いて「キャッシュを消去」をタップし、画面が消えるかロックされると停止します。画面を覆うカバーが動作内容を表示し、キャンセルもできます。何も読み取られず、どこにも送信されません。Android 13 以降では、ファイルからインストールしたアプリは、先に「制限された設定を許可」が必要な場合があります（このアプリの「アプリ情報」、3 点メニュー）。",
