"Apps patched from now on are signed with the new key. Android will not install them over an app that was signed with the old key; export the old one first if you may need it.": "今後パッチを適用するアプリは新しいキーで署名されます。Android は旧キーで署名されたアプリへの上書きインストールを行いません。必要になりそうなら、先に旧キーをエクスポートしてください。",
