"Audio": "オーディオ",
"Aurora Store": "Aurora Store",
"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Storeはオープンソースの Play Store クライアントです。Playのバージョン自動検出は今後対応予定です（匿名のPlay認証が必要）。現時点では、各アプリをストアページに案内し、Aurora Storeがインストールされていればそれを開きます。",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store：インストール済み · Play Store：インストール済み。下のアプリをタップするとストアページが開きます。",
"Aurora Store: installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store：インストール済み · Play Store：未インストール。下のアプリをタップするとストアページが開きます。",
"Aurora Store: not installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store：未インストール · Play Store：インストール済み。下のアプリをタップするとストアページが開きます。",
"Aurora Store: not installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store：未インストール · Play Store：未インストール。下のアプリをタップするとストアページが開きます。",
