"Browser Use finished without an answer.": "Browser Use は答えなしで終了しました。",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "Browser Use はオープンソースのブラウザエージェントです。これはそのホスト型クラウドで、新規アカウントには無料枠があります。Ask agent ボタンは、質問をウェブで調べる短いブラウザタスクを開始します。1～2分かかることがあり、少しクレジットを使います。Ask agent ボタン専用で、チャットではありません。キーのテストは無料です。",
"Browser Use took too long (over 4 minutes). Try again later.": "Browser Use に時間がかかりすぎました（4分以上）。後でもう一度お試しください。",
"Browser Use was stopped before it had an answer.": "Browser Use は答えを得る前に停止されました。",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "ブラウザの自動操作。Nodeと、Chromiumのダウンロードが必要で、スマートフォンでは負荷が大きいことがあります。",
