"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "ログイン方法は、各エージェントの接続シートで選びます。Android版がないツールは、Termux内のDebian環境にインストールされます。これには数分かかり、最大で約1 GBを使用します。プロバイダはAndroidを公式にはサポートしていないため、ツールがすべての端末で動作するとは限りません。",
"Choose the version and tap its download button. The file is saved here and the browser closes by itself.": "バージョンを選び、ダウンロードボタンをタップしてください。ファイルが保存されると、ブラウザは自動的に閉じます。",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "アプリ一覧の各行にある追加ボタンの動作を選びます。ボタンは常にアイコンで表示され、アプリに応じて変わる項目（有効化 / 無効化、インストール / アンインストール、一時停止を解除 / 一時停止）は、アプリの現在の状態に合わせてアイコンと動作が切り替わります。",
"Choose what to install and which starter files to write": "インストールするものと書き込む初期ファイルを選びます",
"Choosing a folder needs the app build": "フォルダの選択には app ビルドが必要です",
"Choosing files works in the app": "ファイルの選択はアプリ版で使えます",
"Chosen:": "選択中：",
