"Claude": "Claude",
"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude ProまたはMax、およびGoogleアカウントのログインは、各プロバイダ自身のアプリでしか使えません。AnthropicとGoogleは、他のアプリがそれらのログインを使うことを認めていないためです。そこでターミナルは、Termuxで動作する公式のコマンドラインツールを通じてログインします。その際、プロバイダ自身のWebサイトのログイン画面が開きます：",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "不要になったものを整理します：余分なファイル、アプリの削除可能なデータ、消えたアプリの残骸、重複しているファイル。先にスキャンし、リストを確認して、残したいものを外してから削除します。4 つのツールは、通常のアプリでは読めないフォルダに対して、このアプリの動作モードを使います。",
"Clean — no engine flagged this file": "問題なし — このファイルを検出したエンジンはありません",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "クリーンアップはシミュレーションです。ファイルはスキャンされ報告されますが、実際には何も削除されません。",
