"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "Crawl4AI はこれに対する答えを見つけられませんでした。ウェブ検索か別のエージェントをお試しください。",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "Crawl4AI はオープンソースのウェブクローラーです。これはそのホスト型クラウドで、新規アカウントには無料クレジットと毎月の無料枠が付き、カードは不要です。Ask agent ボタンは質問を回答サービスに送り、ウェブを検索してページを読み、答えを書きます。Ask agent ボタン専用で、チャットではありません。テストではクレジットを1つ使います。",
