"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMindはMCPサーバーです。ADB経由でAndroid端末を操作する機能（アプリ、ファイル、ログ、スクリーンショット）をAIエージェントに提供するツールで、単体ではチャットできません。",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMindはDebianにインストールされました。次のコマンドで起動します：proot-distro login debian -- ~/.local/bin/droidmind --transport sse。エージェントにMCPサーバーとして追加してください（アドレスは起動時に表示されます）。",
