"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "各エージェントは、公式のログインと同じように、この設定を自分のファイルに保存します。そのため、2つ以上のエージェントに同じサーバーを登録して、どちらからでも使えます。Codexは、リモートサーバーのトークンをファイルではなく環境変数として保持します。すべてのツールのすべてのバージョンでテストされているわけではありません。",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "各シェルは専用の画面を持ち、他のタブを使っている間も開いたままです。cd、export、変数は次のコマンドに引き継がれます。「シェルを再起動」で新しいシェルを開始します。",
"Each wait is 600 seconds (10 minutes) at most.": "各待機は最長 600 秒（10 分）です。",
