"Edited": "編集済み",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "APKを編集すると内容が変わるため、署名が一致しなくなります。再署名するまでAndroidはインストールしません。「署名」を使ってください（このアプリは独自のキーで署名します）。",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "APKを編集すると内容が変わるため、署名が一致しなくなります。再署名するまでAndroidはインストールしません。「署名」を使うと、このアプリのキーで署名できます。",
"Effort": "推論の強度",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "推論の強度は、そのAPIにこの設定項目があるエージェント（Claude、ChatGPT、Gemini、Grok）でのみ効果があります。それ以外のエージェントでは設定は保持されますが、APIキーでチャットするときは何の効果もなく、どのエージェントも、Termux上の独自のログインツールには渡しません。",
