"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "F-Droidカタログ、または既知のサードパーティリポジトリにあるすべてのアプリ。リポジトリを選び、カテゴリで探して、そのままインストールできます — ダウンロードは、リポジトリが公開しているSHA-256と照合されます。",
"Every app that is not enabled is saved.": "有効でないアプリはすべて保存されます。",
