"Exa": "Exa",
"Exa found no answer for this one. Try Web search, or another agent.": "Exaはこの質問への答えを見つけられませんでした。Web検索か別のエージェントをお試しください。",
"Exa is a search engine built for AI. Its answer service searches the web and writes a short answer that names its sources. A new account gets free credits. Testing the key makes one small search (a fraction of a cent). An Ask agent button sends it the question; nothing is sent until you press one.": "ExaはAI向けに作られた検索エンジンです。回答サービスがWebを検索し、情報源を示した短い回答を書きます。新規アカウントには無料クレジットが付きます。キーのテストでは小さな検索を1回行います（1セントにも満たない額）。「エージェントに聞く」ボタンを押すとExaに質問が送られます。ボタンを押すまで何も送信されません。",
