"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "この端末上のアプリのコード内のクラス名を読み取って検出しました。何もどこにも送信されません。トラッカーリスト：Exodus Privacy（ODbL 1.0 ライセンス）。縮小ツール（R8、ProGuard）で名前が変わったコードや後から読み込まれるコードはトラッカーを隠すことがあるため、数が少なくても存在しない証拠にはなりません。",
