"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "ファイル管理から：特権バックエンド経由でインストールし、このアプリの署名チェックはオフにします。ただしAndroid自身は署名を検証します。署名を検証できないAPKはこのアプリのキーで署名してからインストールされ、他の人が署名したアプリは、アンインストールしてからでないと置き換えられません（事前に確認します）。",
