"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leonは、Node.jsとPythonを使ってパソコン上で動作する、オープンソースのパーソナルアシスタント（スキル、音声）です。Android版はなく、コーディングエージェントでもないため、このターミナルではチャットできません。",
