"Let them act without asking": "確認なしで操作させる",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "コマンドの末尾で指定したフォルダ内のファイルを、エージェントが読み書きできるようにします（/sdcardは好みに合わせて変更してください）。",
