"No account, no ads, no analytics and no server of ours. Everything runs on your phone. The app only goes online for something you open or ask for: update checks, App Stores, the debloat list, and a VirusTotal lookup if you add your own key.": "アカウント不要、広告なし、アナリティクスなし、当方のサーバーもありません。すべて端末上で動作します。アプリがオンラインになるのは、開いた操作や求めた操作のときだけです：更新の確認、アプリストア、デブロートリスト、そして自分のキーを追加した場合のVirusTotal検索。",
