"Ollama": "Ollama",
"Ollama (on-device)": "Ollama（端末内）",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "この端末ではまだOllamaが実行されていません。下からインストールするか、Ollamaを実行しているパソコンのアドレスを入力してください。",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone. Ollama on a computer works too: let it listen on all addresses there, then enter the computer's address here (like 192.168.1.20:11434/v1).": "Ollama はコーディング用モデルをこのスマートフォン上で直接実行します：無料で、モデルをダウンロードした後はオフラインでも使えます。Termux にインストールされ、スマートフォンでは小さなモデル（1.5B～3B）が最適です。コンピューター上の Ollama も使えます：そちらですべてのアドレスで待ち受けるようにし、コンピューターのアドレスをここに入力します（例：192.168.1.20:11434/v1）。",
"On": "オン",
"On device": "端末内",
"On this phone": "この端末",
"On:": "オン：",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "各シェルで一度に実行できるコマンドは1つです。長い出力は、画面上でもエージェントに送る内容でも切り詰められます。",
"One file only": "1ファイルのみ",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "アプリ全体で 1 つのキー。インストーラーのスキャンと Morphe Helper のスキャンの両方がこれを使います。どちらも再入力は求めず、キーがないときだけここを案内します。",
"One more place to find apps": "アプリを見つける場所がもう 1 つ",
"One package per line. Duplicate entries are removed automatically.": "1行に1つのパッケージを入力します。重複する項目は自動的に削除されます。",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "1 つのソースカラーを、アクセント、背景、カード、文字をライトとダークで揃えた完全なテーマにする 9 つの方法。スタイルを選ぶと、下のソースカラーからテーマが作られます。",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "AppCleaner だけが使います。ファイルアクセスでは届かないキャッシュのために、各アプリのシステムの「アプリ情報」画面を開いて「キャッシュを消去」をタップします。ほかのことはせず、それらの画面以外の画面内容は読み取らず、画面が消えると停止します。",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "これらのファイルには目印付きのブロックだけが書き込まれます。すでにある内容は残り、再実行すると別のブロックを追加せずに既存のブロックを更新します。",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "信頼できるソースのみ追加してください。パッチソースによって、パッチ適用後のアプリの中身が決まります。",
"Only apps installed on this phone": "この端末にインストール済みのアプリのみ",
"Only base": "ベースのみ",
"Only hidden files are here. Tick Show hidden files to see them.": "ここには隠しファイルのみがあります。「隠しファイルを表示」にチェックを入れると表示されます。",
"Only include common media files, documents and archives.": "一般的なメディアファイル、ドキュメント、アーカイブのみ含めます。",
"Only list what would run for each app. Nothing is run.": "各アプリで実行される内容を一覧表示するだけで、何も実行しません。",
"Only patches for apps installed on this phone": "この端末にインストール済みのアプリ用パッチのみ",
"Only split bundles are listed for this app. Turn on Allow split APK.": "このアプリにはスプリットバンドルのみ一覧にあります。「スプリットAPKを許可」をオンにしてください。",
"Only text and compiled XML files can be compared line by line": "行単位で比較できるのは、テキストとコンパイル済みXMLファイルのみです",
"Only the app name you typed is sent.": "入力したアプリ名のみが送信されます。",
"Only the lines written by the app you pick": "選んだアプリが書き込んだ行のみ",
"Only the selected apps are saved.": "選択したアプリのみが保存されます。",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "変わるのはこのアプリの文字だけです。コード用のボックス内の名前、パス、コマンドは元のフォントのままです。",
"Only this sample question is sent to them: whether the Calculator package can be disabled.": "送られるのはこのサンプルの質問だけです：電卓パッケージを無効にできるかどうか。",
