"Pick an agent under Coding Agents to chat": "チャットするには「コーディングエージェント」でエージェントを選んでください",
"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "エージェントを選び、続けてモデルと推論の強度（低、バランス、高：どこまで深く考えさせるか）を選びます。初回は、どちらもバランス型の設定で始まり、エージェントが必要なもの（APIキー、サーバーアドレス、ログイン）を求めて、開始前にテストします。",
