"Termux could not be opened. Is it installed?": "Termuxを開けませんでした。インストールされていますか？",
"Termux does not accept commands from other apps yet. In Termux, run:": "Termuxはまだ他のアプリからのコマンドを受け付けません。Termuxで次を実行してください：",
"Termux does not take commands from other apps yet: run the command of step 3 in Termux, then test again.": "Termuxはまだ他のアプリからのコマンドを受け付けていません。ステップ3のコマンドをTermuxで実行してから、もう一度テストしてください。",
"Termux is free. Get it from F-Droid or GitHub; the old Google Play build is not suitable.": "Termuxは無料です。F-DroidまたはGitHubから入手してください。Google Playにある古い版は適していません。",
"Termux is not installed. It is free from F-Droid or GitHub.": "Termuxがインストールされていません。F-DroidまたはGitHubから無料で入手できます。",
"Termux is not set up for this app yet.": "Termuxはまだこのアプリ用にセットアップされていません。",
"Termux is ready: vim, nano, git and python are installed and bash has its starter .bashrc. Open the real terminal for full-screen programs.": "Termux の準備ができました：vim、nano、git、python がインストールされ、bash に初期の .bashrc があります。全画面プログラムには本物のターミナルを開いてください。",
"Termux permission": "Termuxの権限",
"Termux setup": "Termuxのセットアップ",
"Termux shells read ~/.bash_profile or ~/.profile first (PATH and the like). Turn off if your profile starts another program.": "Termuxのシェルは、最初に ~/.bash_profile または ~/.profile を読み込みます（PATHなど）。プロファイルが別のプログラムを起動する場合はオフにしてください。",
"Test": "テスト",
"Test and save": "テストして保存",
"Test and save the token": "トークンをテストして保存",
"Test it in Settings": "設定でテスト",
