"Test the Default Ask Agent": "既定の質問エージェントをテスト",
"Test the connection": "接続をテスト",
"Testing the key…": "キーをテストしています…",
"Testing…": "テスト中…",
"Text": "テキスト",
"Text copied": "テキストをコピーしました",
"Text editor": "テキストエディタ",
