"Text.": "テキストです。",
"That address could not be read.": "そのアドレスを読み取れませんでした。",
"That could not start": "開始できませんでした",
"That did not work": "うまくいきませんでした",
"That does not look like a web address.": "ウェブアドレスのようには見えません。",
"That file could not be added": "そのファイルを追加できませんでした",
"That file could not be used": "そのファイルを使用できませんでした",
"That is already in this folder": "すでにこのフォルダにあります",
"That is not a Hidden Settings backup from this app": "このアプリの隠し設定のバックアップではありません",
"That is not a backup file (it is not JSON).": "バックアップファイルではありません（JSON ではありません）。",
"That is not a presets file from this app": "これはこのアプリのプリセットファイルではありません",
"That is not a saved-lists backup from this app.": "このアプリの保存リストのバックアップではありません。",
"That is not a valid pattern, so it is searched as plain text.": "有効なパターンではないため、通常のテキストとして検索します。",
"That is not a valid profile": "有効なプロファイルではありません",
"That is not an APK, APKS, APKM or XAPK file": "APK、APKS、APKM、XAPK のファイルではありません",
"That is the density now": "それが現在の画面密度です",
"That name is already used here": "その名前はここですでに使われています",
"That name is not allowed": "その名前は使用できません",
"That one would stop the adb this app runs on, so it is not sent.": "このアプリが動作しているadbを停止してしまうため、そのコマンドは送信されません。",
"That part of the guide is not there.": "ガイドにその項目はありません。",
"That password did not work. Try again.": "そのパスワードは正しくありません。もう一度お試しください。",
"That pattern could freeze the list (a repeat inside a repeat, or very long), so it is searched as plain text.": "そのパターンはリストが固まる可能性があるため（繰り返しの中の繰り返し、または非常に長い場合）、通常のテキストとして検索します。",
"That port is used by this phone's own ADB. Use another, like 4444.": "そのポートはこの端末自身のADBが使っています。4444など、別のポートを使ってください。",
"That recording could not be read": "その記録を読み込めませんでした",
