"The shell did not start": "シェルが起動しませんでした",
"The signing key that apps patched or re-signed here are signed with. Export it to keep a copy, and import it on another phone, so those apps keep updating in place.": "ここでパッチ適用または再署名したアプリの署名に使う鍵です。コピーを保管するためにエクスポートし、別の端末でインポートすると、それらのアプリをそのまま更新し続けられます。",
