"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "次に、このアプリに「Run commands in Termux environment」を許可して、接続をテストします。ターミナルの設定にある「Termuxのセットアップ」で順を追って案内します。",
"There are no saved lists to back up yet": "バックアップする保存リストはまだありません",
"There are no saved lists to back up yet; Restore works anyway.": "バックアップする保存リストはまだありませんが、復元は使えます。",
"There are no saved lists to share yet": "共有する保存リストはまだありません",
"There are no usable lists in that file.": "そのファイルに使えるリストはありません。",
"There is no key yet": "キーはまだありません",
"There is no undo.": "元に戻すことはできません。",
"There is nothing to delete. Scan first.": "削除するものがありません。先にスキャンしてください。",
"These apps are currently selected for this action:": "この操作に現在選択されているアプリ：",
"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "これらのアプリはアンインストール済みですが、データフォルダはまだ端末に残っています。チェックしたアプリのデータは完全に削除されます。",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "これらのアプリはアンインストール済みです。Root がないと、どのアプリにデータが残っているかをアプリは確認できないため、すべてを消去しても安全ですが、一部では何も見つからない場合があります。チェックしたアプリのデータは完全に削除されます。",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "これらのアプリのリリースは、このアプリが直接確認できないサイトにあります。Obtainiumで追跡できます。",
"These files are too different to compare line by line. View each one instead.": "これらのファイルは差が大きすぎて、行単位で比較できません。代わりに1つずつ表示してください。",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "ブラウザを閉じても続行されます。一時停止はダウンロード済みの分を保持し、再開はサイトに残りだけを要求します（対応していないサイトではファイルを最初からやり直します）。",
"They will be skipped unless you patch anyway, which may fail or break the app.": "それでもパッチを適用しない限りスキップされます。失敗したりアプリが壊れたりする可能性があります。",
