"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "このアプリはストレージを読み取れません。「すべてのファイルへのアクセス」を許可するか、フォントファイルを手動で選んでください（手動なら許可は不要です）。",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "このアプリは特定のタッチスクリーン、キーボード、ナビゲーションを要求しません（uses-configurationエントリなし）。そのため、この端末にあるものでそのまま動作します。",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "このアプリは、必要なハードウェアやソフトウェアの機能を宣言していません（uses-featureエントリなし）。",
"This app has no activities.": "このアプリにはアクティビティがありません。",
"This app may not run commands in Termux yet.": "このアプリは、まだTermuxでコマンドを実行できない可能性があります。",
"This app now has its own private ADB key. Tap the mode badge for details.": "このアプリ専用の非公開ADBキーが作成されました。詳しくはモードのバッジをタップしてください。",
"This app's code could not be read (it has none, or the file is not readable), so nothing can be said about trackers.": "このアプリのコードを読み取れなかった（コードがないか、ファイルが読めない）ため、トラッカーについては何も言えません。",
"This app's own authorization code. Nothing accepts it yet: it is kept here for later. It is made on this phone, stays on this phone, and you can replace it at any time.": "このアプリ専用の認証コードです。今はまだ何も受け付けていません。将来のためにここに保管されています。このスマートフォンで作成され、このスマートフォンから出ることはなく、いつでも置き換えられます。",
"This app's own shell - no root, ADB or package manager.": "このアプリ独自のシェルです。Root、ADB、パッケージマネージャーは使えません。",
"This app's own storage (private)": "このアプリ専用のストレージ(非公開)",
"This app's own user and group id": "このアプリ自身のユーザーIDとグループID",
"This app’s key · 2048-bit RSA · in secure hardware": "このアプリのキー · 2048ビットRSA · セキュアハードウェア内",
