"This build of the app does not contain the Morphe engine, so patching is not available. Sources, the community finder and downloads still work. Install a release build of the app to patch.": "このビルドのアプリには Morphe エンジンが含まれていないため、パッチ適用はできません。ソース、コミュニティ検索、ダウンロードは引き続き使えます。パッチを適用するには、アプリのリリースビルドをインストールしてください。",
"This build of the app does not contain the Morphe engine. Install a release build.": "このビルドのアプリには Morphe エンジンが含まれていません。リリースビルドをインストールしてください。",
"This can cut the ADB connection this app uses, so you may not be able to change it back from here.": "このアプリが使用しているADB接続が切断される可能性があるため、ここから元に戻せなくなることがあります。",
