"To search storage for fonts, this app needs All-files access. You can also choose a font file by hand, which needs no access.": "ストレージのフォントを検索するには、このアプリに「すべてのファイルへのアクセス」が必要です。フォントファイルを手動で選ぶ場合は許可は不要です。",
