"To use DroidMind with an agent that speaks MCP (such as Claude Code or OpenCode), install it into the Debian container in Termux. Then start it with droidmind --transport sse and add it to that agent as an MCP server.": "MCPに対応したエージェント（Claude CodeやOpenCodeなど）でDroidMindを使うには、Termux内のDebianコンテナにインストールします。その後、droidmind --transport sse で起動し、そのエージェントにMCPサーバーとして追加してください。",
