"Type an app name or package name.": "アプリ名またはパッケージ名を入力してください。",
"Type in the search box to find a word anywhere in the guide. This guide is in English.": "検索ボックスに入力すると、ガイド内のあらゆる場所から単語を探せます。このガイドは英語です。",
