"You can grant or revoke it here.": "ここで許可または取り消せます。",
"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "このAPKを編集したため、署名が無効になりました。Androidはこのままではインストールしません。",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "あなたは、Android の隠し設定（Settings.Global、Settings.Secure、Settings.System データベースのエントリで、「settings get/put」が読み書きするもの）を、開発者ではない人に説明します。",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "あなたは、Android の隠し設定（Settings.Global、Settings.Secure、Settings.System データベースのエントリで、「settings get/put」が読み書きするもの）を、開発者ではない人に説明します。簡潔に述べてください：何を制御するか、値の意味、変更すると何が起こるか、変更しても安全か。設定を知らない場合（多くは端末メーカー固有です）は推測せずにはっきりそう述べ、その後で名前から推測できることを述べてください。短い段落で、見出しは付けないでください。",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "あなたは、Android の logcat エントリを、開発者ではない人に説明します。平易な言葉で簡潔に述べてください：この行の意味、",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "あなたは、Android の logcat エントリを、開発者ではない人に説明します。平易な言葉で簡潔に述べてください：この行の意味、最も可能性の高い原因、重要かどうか（無害なノイズか、実際の問題か、クラッシュか）、重要なら何を試すべきか。短い段落で、見出しは付けないでください。行が難解すぎて自信を持って説明できない場合は、そう述べ、ほかに何が役立つかを述べてください。詳細を作り上げないでください。",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "あなたは、AndroidターミナルでのADBとシェルコマンドの構文を手伝います。簡潔かつ実用的に答えてください。",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "あなたは、AndroidターミナルでのADBとシェルコマンドの構文を手伝います。簡潔かつ実用的に答えてください。ユーザーにここで実行してもらうコマンドをちょうど1つ提案するときは、それだけを次の中に入れてください",
